//! Byte-oriented letter-casing helpers, mirroring the C locale `toupper` /
//! `tolower` semantics of the original C++ implementation: only ASCII
//! letters are affected, every other byte passes through unchanged.

pub fn to_upper(b: u8) -> u8 {
    if b.is_ascii_lowercase() {
        b - 32
    } else {
        b
    }
}

pub fn to_lower(b: u8) -> u8 {
    if b.is_ascii_uppercase() {
        b + 32
    } else {
        b
    }
}

/// Uppercase the first byte of `s`, leave the rest untouched.
pub fn uppercase_first(s: &[u8]) -> Vec<u8> {
    let mut out = s.to_vec();
    if let Some(first) = out.first_mut() {
        *first = to_upper(*first);
    }
    out
}

