//! Pluralization / singularization rules.
//!
//! The reference implementation is intentionally naive: pluralizing appends
//! a single `s` and singularizing strips a single trailing `s`. No irregular
//! or suffix-based rules are applied.

/// `pluralize("cat") -> "cats"`. An empty word stays empty.
pub fn pluralize(word: &[u8]) -> Vec<u8> {
    let mut out = word.to_vec();
    if !out.is_empty() {
        out.push(b's');
    }
    out
}

/// `singularize("cats") -> "cat"`: removes exactly one trailing `s`.
pub fn singularize(word: &[u8]) -> Vec<u8> {
    let mut out = word.to_vec();
    if out.last() == Some(&b's') {
        out.pop();
    }
    out
}

