//! A from-scratch re-implementation of the inflection routines exposed by
//! the C++ `inflection::Inflector` class, operating on raw bytes so the
//! behavior matches the original byte-oriented C++ exactly (including
//! non-UTF-8-safe pass-through of non-ASCII bytes).

pub mod casing;
pub mod number;

use casing::{to_lower, to_upper, uppercase_first};

pub struct Inflector;

impl Inflector {
    /// Kept for parity with the C++ API; a no-op here.
    pub fn initialize() {}

    /// `pluralize("cat") -> "cats"`
    pub fn pluralize(word: &[u8]) -> Vec<u8> {
        number::pluralize(word)
    }

    /// `singularize("cats") -> "cat"`
    pub fn singularize(word: &[u8]) -> Vec<u8> {
        number::singularize(word)
    }

    /// Lower camel case: `camelize("test_hello_world") -> "testHelloWorld"`.
    /// The first `_`-separated segment is kept as-is; every later segment
    /// gets its first byte uppercased (the rest of the segment is untouched).
    pub fn camelize(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::new();
        for (i, segment) in word.split(|&b| b == b'_').enumerate() {
            if i == 0 {
                out.extend_from_slice(segment);
            } else if !segment.is_empty() {
                out.extend_from_slice(&uppercase_first(segment));
            }
        }
        out
    }

    /// `underscore("TestHelloWorld") -> "test_hello_world"`.
    /// Inserts `_` before every uppercase byte (except at position 0) and
    /// lowercases everything.
    pub fn underscore(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len() + 4);
        for (i, &b) in word.iter().enumerate() {
            if i > 0 && b.is_ascii_uppercase() {
                out.push(b'_');
            }
            out.push(to_lower(b));
        }
        out
    }

    /// Upper camel case: `classify("cat_table") -> "CatTable"`.
    /// Every `_`-separated segment gets its first byte uppercased; the rest
    /// of each segment is untouched. No singularization is performed.
    pub fn classify(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::new();
        for segment in word.split(|&b| b == b'_') {
            if !segment.is_empty() {
                out.extend_from_slice(&uppercase_first(segment));
            }
        }
        out
    }

    /// `tableize("CatClass") -> "cat_classs"`: underscore, then pluralize.
    pub fn tableize(word: &[u8]) -> Vec<u8> {
        Self::pluralize(&Self::underscore(word))
    }

    /// `humanize("cat_id") -> "Cat id"`: replace `_` with spaces and
    /// uppercase the first byte; the rest is left untouched.
    pub fn humanize(word: &[u8]) -> Vec<u8> {
        let mut out: Vec<u8> = word
            .iter()
            .map(|&b| if b == b'_' { b' ' } else { b })
            .collect();
        if let Some(first) = out.first_mut() {
            *first = to_upper(*first);
        }
        out
    }

    /// `titleize("a b") -> "A B"`: uppercase the first byte and any byte
    /// directly following a space; lowercase everything else.
    pub fn titleize(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for (i, &b) in word.iter().enumerate() {
            if i == 0 || word[i - 1] == b' ' {
                out.push(to_upper(b));
            } else {
                out.push(to_lower(b));
            }
        }
        out
    }

    /// `dasherize("hello_world") -> "hello-world"`.
    pub fn dasherize(word: &[u8]) -> Vec<u8> {
        word.iter()
            .map(|&b| if b == b'_' { b'-' } else { b })
            .collect()
    }

    /// `parameterize("The Cat Test") -> "the-cat-test"`: keep ASCII
    /// alphanumerics (lowercased), turn spaces into `-`, drop all other
    /// bytes. Runs are not collapsed.
    pub fn parameterize(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for &b in word {
            if b.is_ascii_alphanumeric() {
                out.push(to_lower(b));
            } else if b == b' ' {
                out.push(b'-');
            }
        }
        out
    }

    /// ASCII-only uppercase.
    pub fn upcase(word: &[u8]) -> Vec<u8> {
        word.iter().map(|&b| to_upper(b)).collect()
    }

    /// ASCII-only lowercase.
    pub fn downcase(word: &[u8]) -> Vec<u8> {
        word.iter().map(|&b| to_lower(b)).collect()
    }

    /// Uppercase the first byte, lowercase the rest (ASCII-only).
    pub fn capitalize(word: &[u8]) -> Vec<u8> {
        let mut out = Vec::with_capacity(word.len());
        for (i, &b) in word.iter().enumerate() {
            out.push(if i == 0 { to_upper(b) } else { to_lower(b) });
        }
        out
    }
}

